import 'package:docx_creator/docx_creator.dart';

void main(){
  final doc = DocxBuilder()
    .addParagraph('Hello World')
    .addTable([
      ['Header 1','Header 2'],
      ['Cell 1','Cell 2']
    ])
    .build();
  doc.saveAsDocx('example.docx');
  doc.saveAsPdf('example.pdf');
}
